 try{validarCsrf();$id=(int)($_POST['id']??0);$nombre=trim($_POST['nombre']??'');$precio=(float)($_POST['precio']??0);$compra=(float)($_POST['precio_compra']??0);$stock=(float)($_POST['stock']??0);$min=(float)($_POST['stock_minimo']??0);$unidad=trim($_POST['unidad']??'')?:'unidad';$catRaw=$_POST['categoria_id']??'';$cat=$catRaw!==''?(int)$catRaw:null;if($nombre==='')throw new RuntimeException('El nombre es obligatorio.');if($precio<0||$compra<0||$stock<0||$min<0)throw new RuntimeException('Los valores no pueden ser negativos.');
  if($id){$st=$conn->prepare("SELECT * FROM productos WHERE id=? FOR UPDATE");$st->bind_param('i',$id);$st->execute();$antes=$st->get_result()->fetch_assoc();if(!$antes)throw new RuntimeException('Producto no encontrado.');$st=$conn->prepare("UPDATE productos SET nombre=?,precio_compra=?,precio=?,stock=?,stock_minimo=?,unidad=?,categoria_id=? WHERE id=?");$st->bind_param('sddddsii',$nombre,$compra,$precio,$stock,$min,$unidad,$cat,$id);$st->execute();if((float)$antes['stock']!==$stock){$dif=$stock-(float)$antes['stock'];$tipo=$dif>0?'entrada':($dif<0?'salida':'ajuste');$origen=$tipo==='entrada'?'compra':($tipo==='salida'?'salida_manual':'ajuste');$cant=abs($dif);$uid=$_SESSION['usuario']['id']??null;$mot='Edición de producto';$obs='Cambio de stock desde Productos';$mv=$conn->prepare("INSERT INTO movimientos_inventario(producto_id,usuario_id,tipo,origen,cantidad,stock_anterior,stock_nuevo,motivo,observacion) VALUES(?,?,?,?,?,?,?,?,?)");$mv->bind_param('iissdddss',$id,$uid,$tipo,$origen,$cant,$antes['stock'],$stock,$mot,$obs);$mv->execute();}registrarHistorial($conn,'productos','editar','Producto actualizado',['producto'=>$id,'nombre'=>$nombre,'precio_anterior'=>$antes['precio'],'precio_nuevo'=>$precio,'stock_anterior'=>$antes['stock'],'stock_nuevo'=>$stock]);flash('success','Producto actualizado.');}
  else{$st=$conn->prepare("INSERT INTO productos(nombre,precio_compra,precio,stock,stock_minimo,unidad,categoria_id,activo) VALUES(?,?,?,?,?,?,?,1)");$st->bind_param('sddddsi',$nombre,$compra,$precio,$stock,$min,$unidad,$cat);$st->execute();$id=$st->insert_id;if($stock>0){$uid=$_SESSION['usuario']['id']??null;$tipo='entrada';$origen='inicial';$mot='Stock inicial';$obs='Producto creado';$mv=$conn->prepare("INSERT INTO movimientos_inventario(producto_id,usuario_id,tipo,origen,cantidad,stock_anterior,stock_nuevo,motivo,observacion) VALUES(?,?,?,?,?,?,?,?,?)");$zero=0.0;$mv->bind_param('iissdddss',$id,$uid,$tipo,$origen,$stock,$zero,$stock,$mot,$obs);$mv->execute();}registrarHistorial($conn,'productos','crear','Producto creado',['producto'=>$id,'nombre'=>$nombre,'precio'=>$precio,'stock'=>$stock]);flash('success','Producto creado.');}
 }catch(Throwable $e){flash('error',$e->getMessage());}redir('productos.php');
}
