ay=ok?'':'none';if(ok)n++;});const z=document.getElementById('resultadoProductos');if(z)z.textContent=n+' producto'+(n===1?'':'s')+(x?' encontrado'+(n===1?'':'s'):' activo'+(n===1?'':'s'));});</script>
